pub fn pluralize(word: &str) -> String {
    if word.is_empty() {
        String::new()
    } else {
        let mut result = String::with_capacity(word.len() + 1);
        result.push_str(word);
        result.push('s');
        result
    }
}

pub fn singularize(word: &str) -> String {
    if word.ends_with('s') {
        word[..word.len() - 1].to_string()
    } else {
        word.to_string()
    }
}

pub fn camelize(word: &str) -> String {
    let mut result = String::with_capacity(word.len());
    let mut uppercase_next = false;
    let mut seen_non_separator = false;

    for ch in word.chars() {
        if ch == '_' {
            uppercase_next = true;
            continue;
        }

        if uppercase_next {
            result.push(ch.to_ascii_uppercase());
            uppercase_next = false;
        } else {
            result.push(ch);
        }

        seen_non_separator = true;
    }

    if !seen_non_separator {
        String::new()
    } else {
        result
    }
}

pub fn underscore(word: &str) -> String {
    let mut result = String::with_capacity(word.len() * 2);
    let mut is_first = true;

    for ch in word.chars() {
        if ch.is_ascii_uppercase() {
            if !is_first {
                result.push('_');
            }
            result.push(ch.to_ascii_lowercase());
        } else {
            result.push(ch);
        }
        is_first = false;
    }

    result
}

pub fn classify(word: &str) -> String {
    uppercase_first_ascii(&camelize(&singularize(word)))
}

pub fn tableize(word: &str) -> String {
    pluralize(&underscore(word))
}

pub fn humanize(word: &str) -> String {
    uppercase_first_ascii(&word.replace('_', " "))
}

pub fn dasherize(word: &str) -> String {
    word.replace('_', "-")
}

pub fn upcase(word: &str) -> String {
    word.chars().map(|ch| ch.to_ascii_uppercase()).collect()
}

pub fn downcase(word: &str) -> String {
    word.chars().map(|ch| ch.to_ascii_lowercase()).collect()
}

fn uppercase_first_ascii(word: &str) -> String {
    let mut chars = word.chars();
    let Some(first) = chars.next() else {
        return String::new();
    };

    let mut result = String::with_capacity(word.len());
    result.push(first.to_ascii_uppercase());
    result.extend(chars);
    result
}

